#!/usr/bin/env python3
"""Marker header for generated files: `GENERATED by sox install from <sources>; hash=<sha256 of the body>`.

The body is the file text without the marker line, so editing a generated file by hand changes the body and the hash
no longer matches. Markdown carries the marker as an HTML comment (or a frontmatter field), JSON under `_generated`.
Used by tools/install.py and core/targets.py; stdlib only.
"""

from __future__ import annotations

import hashlib
import json
import re

PREFIX = "GENERATED by sox install from "
MARKER = re.compile(r"GENERATED by sox install from (?P<sources>[^;\n]*); hash=(?P<hash>[0-9a-f]{64})")


def digest(text: str) -> str:
    """sha256 of the body; trailing newlines do not count, so a file may end with one newline more or less than its body."""
    return hashlib.sha256(text.rstrip("\n").encode("utf-8")).hexdigest()


def marker_text(sources: list[str], body: str) -> str:
    return f"{PREFIX}{', '.join(sources)}; hash={digest(body)}"


def stamp(body: str, sources: list[str], at: int = 0, style: str = "comment") -> str:
    """Insert the marker as its own line before line `at` of `body` (style `comment`: HTML comment, `field`: frontmatter field)."""
    text = marker_text(sources, body)
    line = f"<!-- {text} -->" if style == "comment" else f'generated: "{text}"'
    lines = body.split("\n")
    lines.insert(at, line)
    return "\n".join(lines)


def stamp_frontmatter(body: str, sources: list[str]) -> str:
    """Stamp a markdown file that starts with YAML frontmatter (the field goes last in it); else a top comment."""
    lines = body.split("\n")
    if lines and lines[0] == "---" and "---" in lines[1:]:
        return stamp(body, sources, at=lines.index("---", 1), style="field")
    return stamp(body, sources)


def unstamp(text: str) -> tuple[str, str | None]:
    """Return (body without the marker line, hash claimed by the marker or None when there is no marker)."""
    lines = text.split("\n")
    for index, line in enumerate(lines):
        match = MARKER.search(line)
        if match:
            return "\n".join(lines[:index] + lines[index + 1:]), match.group("hash")
    return text, None


def verify(text: str) -> str:
    """`ok`, `hand-edited` (body no longer matches the marker hash) or `unmarked`."""
    body, claimed = unstamp(text)
    if claimed is None:
        return "unmarked"
    return "ok" if digest(body) == claimed else "hand-edited"


def _json_body(data: dict) -> str:
    return json.dumps({k: v for k, v in data.items() if k != "_generated"}, sort_keys=True, ensure_ascii=False)


def stamp_json(data: dict, sources: list[str]) -> dict:
    return {"_generated": marker_text(sources, _json_body(data)), **{k: v for k, v in data.items() if k != "_generated"}}


def verify_json(data: dict) -> str:
    match = MARKER.search(str(data.get("_generated", "")))
    if not match:
        return "unmarked"
    return "ok" if digest(_json_body(data)) == match.group("hash") else "hand-edited"
